// Original expansion content for Graduate Assessment Lab. These records are
// intentionally data-only so future sector packs can reuse the same engines.

function verbalPair(passageId, passage, questions) {
  return questions.map((question, index) => ({
    id: `${passageId}-${index + 1}`,
    passageId,
    passage,
    ...question,
    ...(question.answer === 2 ? { explanation: `Cannot Say: ${question.explanation}` } : {}),
  }));
}

