function sjt(id, difficulty, topic, competency, scenario, prompt, options) {
  return {
    id,
    difficulty,
    topic,
    competency,
    scenario,
    prompt,
    options: options.map(([text, rationale], index) => ({ text, rationale, score: 4 - index })),
  };
}

